      <div class="grid gap-4 sm:grid-cols-3"><div class="audit-panel p-5"><p class="text-xs audit-muted">Matching events</p><p class="mt-2 text-2xl font-extrabold">{{ Number(pagination.total).toLocaleString() }}</p></div><div class="audit-panel p-5"><p class="text-xs audit-muted">History view</p><p class="mt-2 text-sm font-bold">Read-only event records</p><p class="mt-1 text-xs audit-muted">New activity appears when you refresh.</p></div><div class="audit-panel p-5"><p class="text-xs audit-muted">Last refreshed · Philippine time</p><p class="mt-2 text-sm font-bold">{{ refreshedAt ? auditDate(refreshedAt) : 'Loading history…' }}</p></div></div>
      <section class="audit-panel p-5 sm:p-6" aria-label="Filter audit history">
        <div class="mb-4 flex flex-wrap items-center justify-between gap-3"><h2 class="text-sm font-bold">Find an event</h2><button @click="clearFilters" :disabled="!activeFilters" class="text-xs font-semibold text-teal-600 disabled:opacity-40">Clear filters{{ activeFilters ? ' (' + activeFilters + ')' : '' }}</button></div>
        <div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><div class="sm:col-span-2 xl:col-span-1"><label for="audit-search">Search history</label><input id="audit-search" v-model.trim="filters.q" maxlength="120" type="search" placeholder="Name, account, bill, device, or event ID…" class="mt-2 w-full"/></div><div><label for="audit-action">Action</label><select id="audit-action" v-model="filters.action" class="mt-2 w-full"><option value="">All actions</option><option v-for="action in options.actions" :key="action" :value="action">{{ auditLabel(action) }}</option></select></div><div><label for="audit-record">Record type</label><select id="audit-record" v-model="filters.auditable_type" class="mt-2 w-full"><option value="">All records</option><option v-for="type in options.types" :key="type" :value="type">{{ auditType(type) }}</option></select></div><div><label for="audit-source">Performed by</label><select id="audit-source" v-model="filters.actor_type" class="mt-2 w-full"><option value="">All sources</option><option value="user">Staff / administrator</option><option value="system">System</option><option value="device">Device</option></select></div><div><label for="audit-from">From date · Philippines</label><input id="audit-from" v-model="filters.date_from" type="date" class="mt-2 w-full"/></div><div><label for="audit-to">Through date · Philippines</label><input id="audit-to" v-model="filters.date_to" type="date" :min="filters.date_from || undefined" class="mt-2 w-full"/></div></div>
