      </section>
      <section class="audit-panel overflow-hidden">
        <div class="flex flex-wrap items-center justify-between gap-3 border-b border-inherit px-6 py-5"><h2 class="font-bold">Recorded activity</h2><p role="status" class="text-xs audit-muted">{{ loading ? 'Loading events…' : pagination.total ? 'Showing ' + pagination.from + '–' + pagination.to + ' of ' + pagination.total : 'No matching events' }}</p></div>
        <div v-if="loading" role="status" class="p-10 text-center text-sm audit-muted">Loading audit history…</div>
        <div v-else-if="error" role="alert" class="p-8"><p class="text-sm text-rose-500">{{ error }}</p><button @click="load(pagination.current_page)" class="audit-secondary mt-4">Try again</button></div>
        <div v-else-if="!logs.length" class="p-12 text-center"><span class="mx-auto flex h-14 w-14 items-center justify-center rounded-2xl bg-teal-500/10 text-teal-600"><svg class="h-7 w-7" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><path d="M5 3h14v18H5V3Zm4 5h6m-6 4h6m-6 4h4"/></svg></span><h3 class="mt-5 font-bold">{{ activeFilters ? 'No events match these filters' : 'Your history starts here' }}</h3><p class="mt-2 text-sm audit-muted">{{ activeFilters ? 'Adjust the search or date range to explore other activity.' : 'New recorded actions will appear here after you refresh.' }}</p></div>
        <div v-else class="overflow-x-auto"><table class="w-full text-left text-sm"><thead class="audit-soft text-xs audit-muted"><tr><th class="px-5 py-3">Event / recorded time</th><th class="px-5 py-3">Action &amp; context</th><th class="px-5 py-3">Affected record</th><th class="px-5 py-3">Performed by</th><th class="px-5 py-3"><span class="sr-only">Details</span></th></tr></thead><tbody class="divide-y audit-divide"><tr v-for="log in logs" :key="log.id"><td class="whitespace-nowrap px-5 py-5"><span class="text-xs font-bold text-teal-600">#{{ log.id }}</span><p class="mt-2 text-xs audit-muted">{{ auditDate(log.created_at) }}</p></td><td class="max-w-md px-5 py-5"><p class="font-semibold" :class="/failed|deleted|voided/.test(log.action) ? 'text-rose-500' : ''">{{ auditLabel(log.action) }}</p><p class="mt-2 text-xs leading-5 audit-muted">{{ auditSummary(log) }}</p></td><td class="px-5 py-5"><p class="text-xs font-semibold">{{ auditType(log.auditable_type) }} #{{ log.auditable_id ?? '—' }}</p><p v-if="log.subject_label" class="mt-2 text-xs text-teal-600">{{ log.subject_label }}</p></td><td class="px-5 py-5"><p class="text-sm font-semibold">{{ log.actor_name }}</p><span class="audit-soft mt-2 inline-block rounded-full px-2 py-1 text-[10px] font-bold uppercase tracking-wider">{{ log.actor_type }}</span></td><td class="px-5 py-5"><button @click="selectedEvent = log.id" class="audit-secondary whitespace-nowrap" :aria-label="'Inspect event ' + log.id">Inspect event →</button></td></tr></tbody></table></div>
