<script setup>
import { ref } from 'vue'
import AppSidebar from '../components/AppSidebar.vue'
import AuditEventDetails from '../components/audit/AuditEventDetails.vue'
import { useAuditLogs } from '../composables/useAuditLogs.js'
import { auditLabel, auditType, auditDate, auditSummary } from '../utils/auditPresentation.js'
const selectedEvent = ref(null)
const { filters, logs, loading, error, options, pagination, pageNumbers, activeFilters, refreshedAt, load, clearFilters, relatedEvents } = useAuditLogs()
function showRelated(group) { selectedEvent.value = null; relatedEvents(group) }
</script>
